function countSignings(nums: number[], target: number): number {
  const go = (i: number, sum: number): number => {
    if (i === nums.length) return sum === target ? 1 : 0;
    return go(i + 1, sum + nums[i]) + go(i + 1, sum - nums[i]);
  };
  return go(0, 0);
}

