function countSignings(nums: number[], target: number): number {
  const total = nums.reduce((a, b) => a + b, 0);
  if (Math.abs(target) > total) return 0;
  const W = 2 * total + 1, n = nums.length; // index s + total holds sum s
  const dp: number[][] = Array.from({ length: n + 1 }, () => new Array(W).fill(0));
  dp[0][total] = 1;
  for (let i = 1; i <= n; i++) {
    const x = nums[i - 1];
    for (let k = 0; k < W; k++) {
      const plus = k - x >= 0 ? dp[i - 1][k - x] : 0;  // + x: came from sum s − x
      const minus = k + x < W ? dp[i - 1][k + x] : 0;  // − x: came from sum s + x
      dp[i][k] = plus + minus;
    }
  }
  return dp[n][target + total];
}

