        W, n = 2 * total + 1, len(nums)  # index s + total holds sum s
        dp = [[0] * W for _ in range(n + 1)]
        dp[0][total] = 1
        for i in range(1, n + 1):
            x = nums[i - 1]
            for k in range(W):
                plus = dp[i - 1][k - x] if k - x >= 0 else 0  # + x: came from sum s - x
                minus = dp[i - 1][k + x] if k + x < W else 0  # - x: came from sum s + x
                dp[i][k] = plus + minus
        return dp[n][target + total]

