function countSignings(nums: number[], target: number): number {
  const total = nums.reduce((a, b) => a + b, 0);
  if (Math.abs(target) > total || (total + target) % 2 !== 0) return 0;
  const P = (total + target) / 2;
  const ways = new Array(P + 1).fill(0);
  ways[0] = 1;
  for (const v of nums)
    for (let x = P; x >= v; x--) ways[x] += ways[x - v]; // downward: each number once
  return ways[P];
}

