        total = sum(nums)
        if abs(target) > total or (total + target) % 2:
            return 0
        P = (total + target) // 2
        ways = [1] + [0] * P
        for v in nums:
            for x in range(P, v - 1, -1):  # downward: each number once
                ways[x] += ways[x - v]
        return ways[P]

